// packages/knowledge/schemas/shared.ts
import { ObjectId } from "mongodb";
import { z } from "zod";

export const zodObjectId = z.instanceof(ObjectId);

export const baseDocFields = {
  _id: zodObjectId,
  tenantId: z.string().min(1),
  createdAt: z.date(),
  updatedAt: z.date(),
