- [ ] **Step 3: Implement the schemas**

```ts
// packages/knowledge/schemas/sources.ts
import { z } from "zod";
import { baseDocFields } from "./shared";

export const sourceStatusValues = [
  "received",
  "transcribed",
  "extracting",
  "proposed",
  "reviewed",
  "failed",
] as const;

export const sourceSchema = z.object({
  ...baseDocFields,
  type: z.enum(["voice", "email", "manual"]),
  status: z.enum(sourceStatusValues),
  capturedBy: z.string().min(1),
  // The textual payload: transcript (voice), body (email), or pasted text (manual).
  content: z.string().optional(),
  audio: z
    .object({
      blobUrl: z.url(),
      contentType: z.string().min(1),
      durationSeconds: z.number().positive().optional(),
    })
    .optional(),
  email: z
    .object({
      originalSender: z.string().min(1),
      subject: z.string(),
      sentAt: z.date(),
      gmailMessageId: z.string().min(1),
      forwardedBy: z.string().min(1),
    })
    .optional(),
  error: z.string().optional(),
});
export type Source = z.infer<typeof sourceSchema>;
```

```ts
// packages/knowledge/schemas/facts.ts
import { z } from "zod";
import { baseDocFields, zodObjectId } from "./shared";

export const factCategoryValues = [
  "preference",
  "objection",
  "decision-process",
  "relationship",
  "logistics",
  "background",
  "other",
] as const;
export type FactCategory = (typeof factCategoryValues)[number];

export const factAnchorsSchema = z
  .object({
    organizationId: zodObjectId.optional(),
    personId: zodObjectId.optional(),
    engagementId: zodObjectId.optional(),
  })
  .refine(
    (anchors) =>
      Boolean(anchors.organizationId || anchors.personId || anchors.engagementId),
    { message: "A fact must be anchored to at least one entity" }
  );
export type FactAnchors = z.infer<typeof factAnchorsSchema>;

export const factSchema = z.object({
  ...baseDocFields,
  text: z.string().min(1),
  category: z.enum(factCategoryValues),
  anchors: factAnchorsSchema,
  sourceId: zodObjectId,
  confidence: z.number().min(0).max(1),
  confirmedBy: z.string().min(1),
  // Lifecycle (dream cycle): a fact is currently valid iff BOTH are absent.
  validUntil: z.date().optional(),
  supersededBy: zodObjectId.optional(),
  // Stubbed for later semantic search (EU embedding provider).
  embedding: z.array(z.number()).optional(),
});
export type Fact = z.infer<typeof factSchema>;
```

